torch::Tensor fused_cross_entropy_cuda(torch::Tensor logits,
                                       torch::Tensor targets) {
    TORCH_CHECK(logits.is_cuda(),  "logits must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(logits.dtype()  == torch::kFloat32, "logits must be float32");
    TORCH_CHECK(targets.dtype() == torch::kInt64,   "targets must be int64");
    TORCH_CHECK(logits.dim() == 2,  "logits must be {B, C}");
    TORCH_CHECK(targets.dim() == 1, "targets must be {B}");
    TORCH_CHECK(logits.size(0) == targets.size(0),
                "Batch size mismatch between logits and targets");

    const int B = logits.size(0);
    const int C = logits.size(1);

    const int blocks = (B + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;
    const size_t smem_bytes = static_cast<size_t>(C) * WARPS_PER_BLOCK * sizeof(float);
    const bool use_smem = (smem_bytes <= 64 * 1024);

    auto losses = torch::empty({B}, logits.options());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    if (use_smem) {
        fused_cross_entropy_kernel_smem_v2<<<blocks, THREADS_PER_BLOCK,
                                             smem_bytes, stream>>>(
            logits.data_ptr<float>(),
            targets.data_ptr<int64_t>(),
            losses.data_ptr<float>(),
            C, B);
    } else {
        fused_cross_entropy_kernel_regs_v3<<<blocks, THREADS_PER_BLOCK,
                                             0, stream>>>(
            logits.data_ptr<float>(),
            targets.data_ptr<int64_t>(),
            losses.data_ptr<float>(),
            C, B);
    }

    CUDA_CHECK_ERRORS();
    return losses.mean();
}

