// ---------------------------------------------------------------------
// Shared-memory buffered kernel (vectorised load into smem)
// ---------------------------------------------------------------------
__global__ void fused_cross_entropy_kernel_smem_v2(
        const float*  __restrict__ logits,
        const int64_t* __restrict__ targets,
        float*        __restrict__ losses,
        const int num_classes,
        const int total_samples) {

    extern __shared__ float smem[];                // WARPS_PER_BLOCK * num_classes
    const int lane          = threadIdx.x & 31;
    const int warp_in_block = threadIdx.x >> 5;
    const int warp_global   = blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    const int sample        = warp_global;

    if (sample >= total_samples) return;

    const float* sample_logits = logits + sample * num_classes;
    float* warp_smem = smem + warp_in_block * num_classes;
    const int64_t tgt = targets[sample];

    // ---------------------------------------------------------------
    // 1. Load logits -> shared (float4), compute local max
    // ---------------------------------------------------------------
    float local_max = -FLT_MAX;
    const int vec_limit = (num_classes & ~3);

    for (int base = lane * 4; base < vec_limit; base += 128) {
        float4 v = *(const float4*)(sample_logits + base);
        warp_smem[base + 0] = v.x;
        warp_smem[base + 1] = v.y;
        warp_smem[base + 2] = v.z;
        warp_smem[base + 3] = v.w;

        local_max = fmaxf(local_max, v.x);
        local_max = fmaxf(local_max, v.y);
        local_max = fmaxf(local_max, v.z);
        local_max = fmaxf(local_max, v.w);
    }
    // tail
    for (int idx = vec_limit + lane; idx < num_classes; idx += 32) {
        float l = sample_logits[idx];
        warp_smem[idx] = l;
        local_max = fmaxf(local_max, l);
    }

    float warp_max_val = warp_max(local_max);
    warp_max_val       = __shfl_sync(0xffffffff, warp_max_val, 0);

    // ---------------------------------------------------------------
    // 2. Σexp & pick target using cached logits
    // ---------------------------------------------------------------
    float local_sum = 0.f;
    float tgt_logit = 0.f;

    for (int idx = lane; idx < num_classes; idx += 32) {
        float l = warp_smem[idx];
        local_sum += __expf(l - warp_max_val);
        if (idx == tgt) tgt_logit = l;
    }

    float warp_sum_val = warp_sum(local_sum);
    warp_sum_val       = __shfl_sync(0xffffffff, warp_sum_val, 0);

    float warp_tgt_log = warp_sum(tgt_logit);
    warp_tgt_log       = __shfl_sync(0xffffffff, warp_tgt_log, 0);

    // ---------------------------------------------------------------
    // 3. Write loss
    // ---------------------------------------------------------------
    if (lane == 0) {
        float log_p = warp_tgt_log - warp_max_val - logf(warp_sum_val);
        losses[sample] = -log_p;
    }
}

