template <typename T>
__device__ __forceinline__ T warp_max(T v) {
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        v = max(v, __shfl_down_sync(0xffffffff, v, off));
    return v;
}

template <typename T>
__device__ __forceinline__ T warp_sum(T v) {
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        v += __shfl_down_sync(0xffffffff, v, off);
    return v;
}

